 for(const [key,name]of Object.entries(names)){const r=rows[key];if(!r||r.n<1)continue;const p=document.createElement('p');p.className='beef-distance';p.innerHTML='<span>'+esc(name)+' <small>(n = '+n(r.n,0)+')</small></span><strong>'+n(r.mean_km)+' ± '+n(r.sd_km)+' km</strong>';box.append(p);}
 if(!Object.keys(rows).length){const p=document.createElement('p');p.textContent=T('Sem estabelecimentos desses tipos localizados nas fontes consultadas.','No facilities of these types located in the consulted sources.');box.append(p);}
 const note=document.createElement('p');note.className='beef-note';note.textContent=T('Média ± desvio padrão entre locais distintos. Distância em linha reta sobre o elipsoide WGS84, sem trajetos rodoviários. Referência: frigoríficos bovinos ativos nas bases Trase/Radar Verde de 2026. Um único estabelecimento tem desvio padrão zero.','Mean ± population standard deviation across distinct locations. Straight-line distance on the WGS84 ellipsoid, without road routing. Reference: active bovine slaughterhouses in the 2026 Trase/Radar Verde inventories. A single establishment has a standard deviation of zero.');box.append(note);
 const plants=data.plant_eligibility[code]||[],nearest=data.nearest_plant_eligibility[code]||[];const details=document.createElement('details');details.className='beef-details';const summary=document.createElement('summary');summary.textContent=T('Mercados habilitados dos frigoríficos locais · 2026','Approved markets for local slaughterhouses · 2026');details.append(summary);
 if(!plants.length){const p=document.createElement('p');p.textContent=T('Nenhum frigorífico local identificado nessas fontes.','No local slaughterhouse identified in these sources.');details.append(p);}
 for(const plant of plants){const p=document.createElement('p');const status=plant.status==='approved'?plant.countries.map(country).join(', '):plant.status==='not_approved'?T('Sem habilitação para exportar na edição consultada.','Not approved for export in the consulted edition.'):T('Habilitação não informada na fonte.','Export approval unavailable in the source.');p.innerHTML='<b>'+esc(plant.name||T('Nome não informado','Name unavailable'))+'</b><br>'+esc(status);details.append(p);}
 const disclaimer=document.createElement('p');disclaimer.className='beef-note';disclaimer.textContent=T('Habilitação registrada na edição Trase 2026. Indica acesso permitido a mercados, sem informar quanto a planta vendeu ou exportou. Mudanças posteriores exigem consulta ao MAPA.','Approval recorded in the Trase 2026 edition. It indicates permitted market access and does not report plant sales or export volumes. Later changes require a MAPA check.');details.append(disclaimer);if(nearest.length){const refs=document.createElement('details'),rs=document.createElement('summary');rs.textContent=T('Habilitação dos frigoríficos usados nas distâncias','Approval of slaughterhouses used for distances');refs.append(rs);for(const plant of nearest){const p=document.createElement('p');p.innerHTML='<b>'+esc(plant.name||T('Nome não informado','Name unavailable'))+'</b><br>'+esc(plant.status==='approved'?plant.countries.map(country).join(', '):plant.status==='not_approved'?T('Sem habilitação para exportar na edição consultada.','Not approved for export in the consulted edition.'):T('Habilitação não informada.','Approval unavailable.'));refs.append(p);}details.append(refs);}box.append(details);
 box.append(renderOfficialFlows(code));section.append(box);window.ATLAS_BEEF_CONTEXT_READY=code;
